import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's rates, one per grade that has one. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /** Set a grade's rate, replacing the one it had (the sheet is started when it was never loaded before). */
    @Transactional
    public Rate set(String sheetId, String user, Grade grade, BigDecimal pct) {
        sheets.load(sheetId, user);
        Rate rate = rates.findBySheetIdAndGrade(sheetId, grade).orElseGet(() -> new Rate(sheetId, grade, pct));
        rate.setPct(pct);
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString());
        return saved;
    }
}
-- The sheet's rate for a grade: a percent with two decimals (0.00 or more). A grade has at most one
-- rate on a sheet; setting it again replaces it. A grade with no rate has none.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A settled claim's due, fixed when it is settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Later changes to rates (or grades) do not alter it. Open and other
-- claims have none (their due stays live), as does one settled while its grade had no rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(15, 2);
UPDATE claim c SET due = (
    SELECT ROUND(c.amount * r.pct / 100, 2) FROM person p JOIN rate r
        ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { Grade } from './people.service';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export interface Rate {
  grade: Grade;
  /** A percent as text with two decimals, e.g. "12.50". */
  pct: string;
}

// The active sheet's rates, at most one per grade; a grade with no rate has none.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Rate[]>([]);

  readonly rates = this.list.asReadonly();

  /** Each grade's rate, in hundredths of a percent; a grade with no rate is absent. */
  readonly byGrade = computed(() => {
    const out = new Map<Grade, number>();
    for (const r of this.list()) out.set(r.grade, hundredths(r.pct));
    return out;
  });

  /** Re-read the active sheet's rates from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Rate[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((rates) => {
        if (this.sheets.sheetId() === id) this.list.set(rates);
      }));
  }

  set(grade: Grade, pct: string): Observable<Rate> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<Rate>(`${this.url(id)}/${grade}`, { pct }, { headers: this.session.headers() })
      .pipe(tap((r) => this.list.update((all) => [...all.filter((o) => o.grade !== r.grade), r])));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}

/** "12.50" as 1250. */
function hundredths(pct: string): number {
  const [whole, frac = ''] = pct.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
}

/**
 * Cents times a rate (in hundredths of a percent) divided by 100, in cents, rounded half up (a half
 * rounds away from zero). Worked in BigInt so it is exact for any amount.
 */
export function due(cents: number, rate: number): number {
  return Number((BigInt(cents) * BigInt(rate) + 5000n) / 10000n);
}
